"""Fill section 11 of research/STUDY4_PROTOCOL_v0.1.md from outputs/study4_v0.1/VALIDATION.json and INPUTS.json (every number generated, none
typed). Not pinned. Replaces the marker [[VALIDATION_SECTION]] (or the previously generated section between its begin and end markers)."""
import json, pathlib, re, sys
ROOT = pathlib.Path(__file__).resolve().parents[2]
PROTO = ROOT / "research/STUDY4_PROTOCOL_v0.1.md"; OUT = ROOT / "outputs/study4_v0.1"
BEGIN, END = "<!-- generated section 11 begin -->", "<!-- generated section 11 end -->"


def pct(x):
    return f"{100 * x:.1f}%"


def main():
    V = json.loads((OUT / "VALIDATION.json").read_text()); I = json.loads((OUT / "INPUTS.json").read_text()); grid = json.loads((ROOT / "research/study4/grid_v0.1.json").read_text())
    fx = V["fixtures"]; cost = V["cost"]; pl = I["pilot_law"]
    lines = [BEGIN, f"Generated by `research/study4/s4_protocol_fill.py` from `VALIDATION.json` (written {V['written_utc']}; grid `{V['grid_sha256'][:12]}…`; all fixtures ok: **{V['all_ok']}**) and `INPUTS.json` (written {I['written_utc']}). Validation keys only; the record's thresholds stand in for validation keys in the analyzer's validation mode; no scientific meaning attaches to any number of the validation run.", ""]
    f1 = fx["F1_hook_equals_detector"]["detail"]
    f1_h = {h: d for h, d in f1.items() if isinstance(d, dict) and "n_scored" in d}; bc = f1.get("boundary_case_R09_F2", {})
    f1_txt = ", ".join("h = %s: %d scored positions" % (h, d["n_scored"]) for h, d in f1_h.items())
    bc_txt = (f"; the boundary case of R09 F2 (uniform {bc.get('uniform_float64')}, float32 {bc.get('uniform_float32')}): the exact mask agrees with the detector ({bc.get('cache_green')}) where a float32 copy would not ({bc.get('float32_would_say')}); a key switch empties the cache" if bc else "")
    lines.append(f"- **F1, the hooks against the locked detector (synthetic texts, random choices):** green flags and float64 uniforms exactly equal at every scored position at h = 0, 1, 2 ({f1_txt}); the batch context hash equals the scalar one{bc_txt}. Result: {'ok' if fx['F1_hook_equals_detector']['ok'] else 'FAILED'}.")
    f2 = fx["F2_record_binding"]["detail"]
    lines.append(f"- **F2, the binding to Study 3's record:** the 240 files verified against the run manifest, inventory digest `{f2['inventory_sha256'][:12]}…`, lock `{f2['lock_sha256'][:12]}…`, keys {f2['keys'][0]}–{f2['keys'][1]}; refusals on scratch copies: " + "; ".join(f"{k}: {v.split(':')[0]}" for k, v in f2.items() if k not in ('inventory_sha256', 'lock_sha256', 'keys')) + f". Result: {'ok' if fx['F2_record_binding']['ok'] else 'FAILED'}.")
    lines.append(f"- **F3, the core's self-tests** (uniform null p-values; a planted between-key SD recovered; the pooled-law cost predictor against the normal law; the classifications; the calibration-prefix moments against Study 3's pinned inputs): {fx['F3_core_selftests']['detail']}. Result: {'ok' if fx['F3_core_selftests']['ok'] else 'FAILED'}.")
    f4 = fx["F4_analyzer"]["detail"]
    lines.append(f"- **F4, the analyzer on the validation record** ({f4['units']} units; {f4['seconds']} s): accepted with {f4['contract_failures']} contract failures; {f4['W1_rows']} W1 rows, {f4['W2_rows']} W2 rows, {f4['W3_candidates']} W3 candidate rows, {f4['descriptive_rows']} descriptive rows, {f4['null_rows']} null rows; the recomputed calibration-prefix moments differ from Study 3's pinned inputs by at most {f4['null_inputs_max_abs_diff']['max_abs_diff_rho']:.1e} (ρ̄) and {f4['null_inputs_max_abs_diff']['max_abs_diff_sigma2']:.1e} (σ²). Mutations on scratch copies: " + "; ".join(f"{k}: {v.split(':')[0]}" for k, v in f4["mutations"].items()) + f". Result: {'ok' if fx['F4_analyzer']['ok'] else 'FAILED'}.")
    f5 = fx["F5_lock_schema"]["detail"]
    lines.append(f"- **F5, the lock schema** ({f5.get('n_pinned', '')} pinned files; on a scratch copy of the pinned files, placeholders for {len(f5['placeholders_for_missing_pinned_files'])} not yet written at validation time: {', '.join(p.split('/')[-1] for p in f5['placeholders_for_missing_pinned_files']) or 'none'}): a well-formed lock {f5['well_formed']}; variants: " + "; ".join(f"{k}: {v.split(':')[0]}" for k, v in f5.items() if isinstance(v, str) and k not in ('well_formed', 'placeholders_for_missing_pinned_files')) + f". Result: {'ok' if fx['F5_lock_schema']['ok'] else 'FAILED'}.")
    lines.append(f"- **F6, the cost projection from the validation run's own wall-clock** (the runner at the production batch size; {cost['validation_units']} units): per generation unit of {grid['validation']['n_prompts']} texts, " + ", ".join(f"{a}: {s} s" for a, s in cost['wall_seconds_per_gen_unit_by_arm'].items()) + f"; per unwatermarked text {cost['wall_seconds_per_null_text']} s; production inventory {cost['production_units']['gen']} generation units of {grid['prompts']['n_watermarked']} texts and {cost['production_units']['null']} null units of {grid['null_arm']['n_per_unit']}: **{cost['projected_hours']} h projected** (the design arithmetic said 12.7 h at the pilot's batch-32 rates); the runner's peak RSS {cost['model_rss_gb_runner']} GB; the analyzer took {cost['analyzer_seconds_validation']} s on the validation record and its results file would be about {cost['projected_results_json_bytes_rough'] / 1e6:.0f} MB at the production inventory (below the host's 100 MB limit; the per-key arrays go to `results_arrays.npz`). Result: {'ok' if fx['F6_cost_projection']['ok'] else 'FAILED'}.")
    f7 = fx["F7_pilot_law_inputs"]["detail"]
    arms_txt = "; ".join(f"{a}: " + ", ".join(f"{c} {d['power_nominal_0.01_raw256']:.3f} (loop share {d['loop_share']:.3f}, perplexity {d['ppl']})" for c, d in cells.items()) for a, cells in f7["arms"].items())
    lines.append(f"- **F7, the pre-lock inputs:** `INPUTS.json` bound to the current prompt manifest, pilot manifest and grid ({f7['provenance_bound_to_current_manifest_and_grid']}); the pilot law of every arm on every prompt cell on validation keys {pl['keys'][0]}–{pl['keys'][-1]} × {pl['n_prompts']} pilot prompts ({pl['n_prompts'] * len(pl['keys'])} texts per law; the hook flags equal the detector in every law), the nominal power at α = 0.01 under the raw rule at 256 tokens: {arms_txt}; **W1's tolerance per cell by D15's rule** max(5 pp, 2 × the cluster-bootstrap SE), applied ({f7['tolerance_rule_applied']}): " + ", ".join(f"{c} {t} pp (SE {f7['cluster_se_pp'][c]} pp)" for c, t in f7["W1_tolerance_pp"].items()) + "; the human reference perplexity under the admissible law: " + ", ".join(f"{c} {p}" for c, p in f7['human_ppl_admissible_law'].items()) + f". Result: {'ok' if fx['F7_pilot_law_inputs']['ok'] else 'FAILED'}.")
    f8 = fx["F8_prompts_and_keys"]["detail"]
    lines.append(f"- **F8, the prompts and keys:** the production prompt arrays and ids digests equal the manifest's and the plan reproduced the pilot ids in every cell (" + "; ".join(f"{t}: {d['n']} prompts at scan positions {d['positions'][0]}–{d['positions'][1]}" for t, d in f8['cells'].items()) + f"); the K₄ = {grid['keys']['K4']} power keys reproduced from seed {grid['keys']['subset_seed']} ({grid['keys']['power_keys'][0]}, {grid['keys']['power_keys'][1]}, … , {grid['keys']['power_keys'][-1]}); the key policy refuses " + ", ".join(k for k in f8['policy']) + f". Result: {'ok' if fx['F8_prompts_and_keys']['ok'] else 'FAILED'}.")
    f9 = fx.get("F9_rule_row_branches")
    if f9:
        lines.append(f"- **F9, every branch of the rule rows with planted data** (the validation record, with two keys and 96 null texts, reaches only W1's consistent branch, W2's unresolved branch and W3's ineligible branch): " + "; ".join(f"{k}: {v}" for k, v in f9["detail"].items()) + f". Result: {'ok' if f9['ok'] else 'FAILED'}.")
    f10 = fx.get("F10_budget_stop_resume_accounting")
    if f10:
        d10 = f10["detail"]; lines.append(f"- **F10, the budget stop's resume accounting** (model-free; R09 F17): ten new null units after 620 reused units project to {d10['projected_hours_new_units_only']} h on their own ({d10['projected_hours_if_reused_were_credited']} h if the reused units were credited); three hours spent on them stops the run ({d10['three_hours_on_the_new_units_stops']}) where the credited version would not ({d10['three_hours_would_pass_if_reused_were_credited']}). Result: {'ok' if f10['ok'] else 'FAILED'}.")
    if V.get("fixture_tolerances"):
        lines.append("- **The fixtures' acceptance tolerances** (`VALIDATION.json` `fixture_tolerances`): " + "; ".join(f"{k}: {v}" for k, v in V["fixture_tolerances"].items()) + ".")
    s = V["analysis_validation_summary"]
    lines.append(f"- **The validation analysis** (no meaning; the rule paths the record can reach, the rest by F9): W1 {s['W1']}, W2 {s['W2']}, W3 {s['W3']}.")
    lines.append(END)
    txt = PROTO.read_text()
    if "[[VALIDATION_SECTION]]" in txt:
        txt = txt.replace("[[VALIDATION_SECTION]]", "\n".join(lines))
    else:
        txt = re.sub(re.escape(BEGIN) + r".*?" + re.escape(END), lambda m: "\n".join(lines), txt, flags=re.S)
    PROTO.write_text(txt); print("section 11 filled;", len(lines) - 2, "items")


if __name__ == "__main__":
    main()
